<script>
import { Form, Head, Link } from '@inertiajs/vue3';
import InputError from '@scaffold/components/InputError.vue';
import PasskeyVerify from '@scaffold/components/PasskeyVerify.vue';
import PrimaryButton from '@scaffold/components/PrimaryButton.vue';
import { dashboard } from '@app/routes';
import { store } from '@app/routes/password/confirm';

export default {
    name: 'ConfirmPassword',
    components: { Form, Head, InputError, Link, PrimaryButton, PasskeyVerify },
    props: { canUsePasskeys: Boolean },
    data() {
        return {
            confirmPasswordForm: store.form(),
            dashboardUrl: dashboard.url(),
        };
    },
};
</script>

<template>
    <div>
        <Head title="Apstiprināt paroli" />
        <div class="row justify-content-center">
            <div class="lg:col-4 md:col-6 sm:col-8 ms-auto me-auto">
                <div class="card">
                    <div class="card-header card-header-primary text-center">
                        <h1 class="card-title h4">Apstiprināt paroli</h1>
                    </div>
                    <Form
                        v-bind="confirmPasswordForm"
                        reset-on-success
                        reset-on-error
                        v-slot="{ errors, processing }"
                    >
                        <div class="card-body">
                            <p>
                                Lai turpinātu, drošības nolūkos apstipriniet
                                savu pašreizējo paroli.
                            </p>
                            <div class="form-group">
                                <label for="confirm-password"
                                    >Pašreizējā parole</label
                                >
                                <input
                                    id="confirm-password"
                                    name="password"
                                    type="password"
                                    class="form-control"
                                    autocomplete="current-password"
                                    required
                                    autofocus
                                    :aria-invalid="Boolean(errors.password)"
                                    :aria-describedby="
                                        errors.password
                                            ? 'confirm-password-error'
                                            : undefined
                                    "
                                />
                                <InputError
                                    id="confirm-password-error"
                                    :message="errors.password"
                                />
                            </div>
                        </div>
                        <div class="card-footer justify-content-center">
                            <PrimaryButton
                                type="submit"
                                class="btn btn-primary"
                                :disabled="processing"
                            >
                                {{
                                    processing
                                        ? 'Pārbauda…'
                                        : 'Apstiprināt paroli'
                                }}
                            </PrimaryButton>
                        </div>
                    </Form>
                    <PasskeyVerify v-if="canUsePasskeys" confirm />
                    <p class="text-center mb-3">
                        <Link :href="dashboardUrl">Atgriezties sākumlapā</Link>
                    </p>
                </div>
            </div>
        </div>
    </div>
</template>
